// Evolution API manda su propio formato. Acá se normaliza a lo que espera el resto
// del flujo: body.businessId / body.phone / body.message / body.sender.
// El businessId viaja en la query del webhook, así cada negocio tiene su propia URL.
const raw = $('Webhook').item.json;
const query = raw.query || {};
const body = raw.body || {};
const data = body.data || {};

// Formato Evolution
const remoteJid = data?.key?.remoteJid || '';
const phoneFromJid = remoteJid.split('@')[0] || '';
const evolutionText =
  data?.message?.conversation ||
  data?.message?.extendedTextMessage?.text ||
  data?.message?.imageMessage?.caption ||
  '';

// Si alguien llama al webhook ya normalizado (pruebas), se respeta tal cual.
const businessId = body.businessId || query.businessId || '';
const phone = body.phone || (phoneFromJid ? '+' + phoneFromJid : '');
const message = body.message || evolutionText;
const sender = body.sender || data?.pushName || body.pushName || '';

return [{
  json: {
    body: { businessId, phone, message, sender },
    headers: raw.headers || {},
    fromMe: Boolean(data?.key?.fromMe),
  },
}];
